 renderMacros(t){if(t.id==='master')t=this.store.project.master;const rack=$('#fx-save-preset')?.parentElement;if(!rack)return;const div=document.createElement('div');div.className='rack-macros';div.innerHTML=(t.macros||[]).map(m=>`<div class="field"><label>${this.escape(m.name)} · ${m.maps.length} mappings</label><div class="inline-controls"><input data-macro="${m.id}" type="range" min="0" max="1" step=".001" value="${m.value}"><button data-macro-auto="${m.id}">◇</button><button data-macro-edit="${m.id}" title="Edit mappings">Mappings</button><button data-macro-delete="${m.id}">×</button></div></div>`).join('');rack.after(div);div.querySelectorAll('[data-macro]').forEach(el=>{el.oninput=()=>{this.previewMacro(t,el.dataset.macro,Number(el.value));};el.onchange=()=>this.store.edit('Set rack macro',()=>t.macros.find(m=>m.id===el.dataset.macro).value=Number(el.value));});div.querySelectorAll('[data-macro-edit]').forEach(el=>el.onclick=()=>this.editMacro(t.id||'master',el.dataset.macroEdit));div.querySelectorAll('[data-macro-delete]').forEach(el=>el.onclick=()=>this.store.edit('Delete rack macro',()=>{t.macros=t.macros.filter(m=>m.id!==el.dataset.macroDelete);t.automation=t.automation.filter(a=>a.target!=='macro:'+el.dataset.macroDelete);}));div.querySelectorAll('[data-macro-auto]').forEach(el=>el.onclick=()=>{const m=t.macros.find(m=>m.id===el.dataset.macroAuto);let lane=t.automation.find(a=>a.target==='macro:'+m.id);if(!lane){lane={id:uid(),effectId:null,target:'macro:'+m.id,name:m.name,min:0,max:1,default:m.value,points:[{beat:0,value:m.value,curve:'linear'}]};this.store.edit('Automate rack macro',()=>t.automation.push(lane));}this.activeLane={trackId:t.id||'master',laneId:lane.id};this.setEditor('automation');});}
 editMacro(id,macroId){const t=id==='master'?this.store.project.master:this.store.project.tracks.find(t=>t.id===id),macro=t.macros.find(m=>m.id===macroId);this.modal('Macro mappings',`<input id="macro-edit-name" value="${this.escape(macro.name)}" aria-label="Macro name">${macro.maps.map((map,k)=>`<div class="macro-map-row" data-map-index="${k}"><b>${this.escape(map.effectId?(EFFECTS[t.effects.find(f=>f.id===map.effectId)?.type]?.name||'Removed effect')+' / '+map.key:map.key)}</b><label>At 0<input data-map-field="min" type="number" step="any" value="${map.min}"></label><label>At 1<input data-map-field="max" type="number" step="any" value="${map.max}"></label><label>Curve<input data-map-field="curve" type="number" min=".1" max="8" step=".1" value="${map.curve??1}"></label><button data-map-remove="${k}">Remove</button></div>`).join('')}<p>Right-click or long-press any instrument, send, volume or effect parameter to add a mapping.</p><div class="buttons"><button id="macro-edit-save" class="primary">Save mappings</button></div>`,()=>{$$('[data-map-remove]').forEach(b=>b.onclick=()=>b.closest('[data-map-index]').remove());$('#macro-edit-save').onclick=()=>{const name=$('#macro-edit-name').value.trim()||macro.name,maps=$$('[data-map-index]').map(row=>{const map={...macro.maps[Number(row.dataset.mapIndex)]};row.querySelectorAll('[data-map-field]').forEach(input=>map[input.dataset.mapField]=Number(input.value));map.curve=clamp(map.curve,.1,8);return map;});this.store.edit('Edit macro mappings',()=>{macro.name=name;macro.maps=maps;});$('#dialog').close();};});}
