 spectralDialog(){if(this.selected()?.c.type!=='audio'){this.toast('Select audio first.');return;}this.modal('Spectral processing',`<p>1024-point overlapping FFT processing. The result becomes a new source; the original stays recoverable.</p><div class="dialog-grid"><div class="field"><label>Low frequency · Hz</label><input id="spectral-low" type="number" min="0" max="20000" value="0"></div><div class="field"><label>High frequency · Hz</label><input id="spectral-high" type="number" min="20" max="24000" value="20000"></div><div class="field"><label>Spectral gate</label><input id="spectral-gate" type="number" min="0" max="100" step=".01" value="0"></div><div class="field"><label>Blur · bins</label><input id="spectral-blur" type="number" min="0" max="30" value="0"></div><label><input id="spectral-freeze" type="checkbox"> Freeze first window</label></div><div class="buttons"><button id="spectral-apply" class="primary">Process audio</button></div>`,()=>{$('#spectral-apply').onclick=()=>{const options={low:Number($('#spectral-low').value),high:Number($('#spectral-high').value),gate:Number($('#spectral-gate').value),blur:Number($('#spectral-blur').value),freeze:$('#spectral-freeze').checked};$('#dialog').close();this.processClip('spectral',{options}).catch(this.error);};});}
