 renderAnalysis(){$('#editor-tools').innerHTML='<button id="analyze-mix">Analyze rendered mix</button><button id="reference-import">Load reference</button><button id="reference-toggle">A/B reference</button><button id="loudness-match">Match loudness</button><button id="reference-compare">Compare reference</button><label>View <select id="analysis-view"><option value="spectrum">Spectrum / scope</option><option value="spectrogram">Spectrogram</option><option value="vectorscope">Stereo vectorscope</option></select></label>';$('#editor-body').innerHTML='<div class="analysis-wrap"><canvas id="spectrum"></canvas><canvas id="scope"></canvas><div class="analysis-values" id="analysis-values">Play audio for live spectrum and oscilloscope. Render analysis measures the actual mix.</div></div>';$('#analyze-mix').onclick=async()=>{try{const pcm=await this.engine.render({tail:2},p=>this.status('Analyzing mix '+Math.round(p*100)+'%'));this.mixAnalysis=await this.jobs.run('analysis',pcm);this.updateAnalysis();this.status('Mix analysis complete');}catch(e){this.error(e);}};$('#reference-import').onclick=()=>{this.referenceImport=true;$('#audio-import').click();};$('#reference-toggle').onclick=()=>this.toggleReference().catch(this.error);$('#loudness-match').onclick=()=>this.matchReference().catch(this.error);$('#reference-compare').onclick=()=>this.compareReference().catch(this.error);this.updateAnalysis();}
